package com.smokescapehub.reminders;

import com.smokescapehub.SmokeScapeHubConfig;
import com.smokescapehub.temple.GroupCompetition;
import com.smokescapehub.temple.TempleOsrsClient;
import com.smokescapehub.util.TimeUtil;
import java.time.Instant;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

// Fires chatbox reminders for upcoming TempleOSRS group competitions
// (24h/6h/2h/1h/30m/start before), and a "currently running" message once
// per real login - not on every teleport/region change or world hop, both
// of which also fire GameState.LOGGED_IN. No external data source - this
// rides on the same group_competitions.php data the Comps tab already
// fetches.
//
// State here is touched from three threads - the OkHttp callback thread
// (competition fetches), the 1-minute tick executor thread, and the client
// thread (GameStateChanged) - so the collections are concurrent and the
// competition list is published via a volatile reference.
public class CompetitionReminderManager
{
	private static final int[] THRESHOLD_MINUTES = {1440, 360, 120, 60, 30, 0};
	private static final long MAX_REMINDER_DURATION_SECONDS = 30L * 24 * 60 * 60;

	private final Client client;
	private final ChatMessageManager chatMessageManager;
	private final TempleOsrsClient templeOsrsClient;
	private final SmokeScapeHubConfig config;

	private final Set<String> firedReminders = ConcurrentHashMap.newKeySet();
	private final Set<Integer> knownCompetitionIds = ConcurrentHashMap.newKeySet();
	private volatile List<GroupCompetition> competitions = Collections.emptyList();

	// GameState.LOGGED_IN fires on every region change (teleporting) and on
	// world hops, not just on a real login - RuneLite's own XpTrackerPlugin
	// notes this ("LOGGED_IN is triggered between region changes too").
	// Tracking whether we were already logged in - reset only by actually
	// seeing the login screen - is what correctly limits this to once per
	// real login, ignoring both teleports and hops.
	private volatile boolean wasLoggedIn;

	@Inject
	public CompetitionReminderManager(Client client, ChatMessageManager chatMessageManager, TempleOsrsClient templeOsrsClient, SmokeScapeHubConfig config)
	{
		this.client = client;
		this.chatMessageManager = chatMessageManager;
		this.templeOsrsClient = templeOsrsClient;
		this.config = config;
	}

	// Call once from Plugin#startUp(), in case the plugin is enabled while
	// already logged in mid-session (no GameStateChanged would fire for that).
	public void init()
	{
		wasLoggedIn = client.getGameState() == GameState.LOGGED_IN;
		if (wasLoggedIn)
		{
			announceActiveCompetitions();
		}
	}

	public void refresh(String groupId)
	{
		if (groupId == null || groupId.trim().isEmpty())
		{
			return;
		}

		templeOsrsClient.getGroupCompetitions(groupId.trim(), this::onCompetitionsFetched, error -> { });
	}

	private void onCompetitionsFetched(List<GroupCompetition> fetched)
	{
		// Long-running competitions (the yearly XP comp, etc.) are excluded
		// from reminders entirely - they're active for months at a time, so
		// a "currently running" login message would never stop firing, and
		// countdown reminders are meaningless for something that started
		// long ago. The Comps tab still shows them normally; this only
		// affects notifications.
		List<GroupCompetition> relevant = fetched.stream()
			.filter(c -> c.endDateUnix - c.startDateUnix <= MAX_REMINDER_DURATION_SECONDS)
			.collect(Collectors.toList());

		Instant now = Instant.now();

		for (GroupCompetition competition : relevant)
		{
			if (!knownCompetitionIds.add(competition.id))
			{
				continue;
			}

			// First time seeing this competition: silently mark any threshold
			// already in the past as fired, so we don't dump a burst of
			// "24h/6h/2h ago" reminders the moment it's first fetched.
			long minutesUntilStart = (competition.startDateUnix - now.getEpochSecond()) / 60;
			for (int threshold : THRESHOLD_MINUTES)
			{
				if (minutesUntilStart < threshold)
				{
					firedReminders.add(reminderKey(competition.id, threshold));
				}
			}
		}

		competitions = relevant;
	}

	// Call on a frequent timer (e.g. every minute) - the hourly data refresh
	// is too coarse to reliably hit a 30-minute-before window.
	public void tick()
	{
		if (!config.chatReminders())
		{
			return;
		}

		long nowEpoch = Instant.now().getEpochSecond();

		for (GroupCompetition competition : competitions)
		{
			if (competition.endDateUnix < nowEpoch)
			{
				continue;
			}

			long minutesUntilStart = (competition.startDateUnix - nowEpoch) / 60;

			for (int threshold : THRESHOLD_MINUTES)
			{
				String key = reminderKey(competition.id, threshold);
				if (minutesUntilStart <= threshold && firedReminders.add(key))
				{
					fireReminder(competition, threshold);
				}
			}
		}
	}

	public void onGameStateChanged(GameState newState)
	{
		if (newState == GameState.LOGGED_IN)
		{
			if (!wasLoggedIn)
			{
				announceActiveCompetitions();
			}
			wasLoggedIn = true;
		}
		else if (newState == GameState.LOGIN_SCREEN || newState == GameState.LOGIN_SCREEN_AUTHENTICATOR)
		{
			// Only a real logout puts the client back here - hopping goes
			// through GameState.HOPPING instead, and teleporting/region
			// changes never leave LOGGED_IN at all.
			wasLoggedIn = false;
		}
	}

	private void announceActiveCompetitions()
	{
		if (!config.chatReminders())
		{
			return;
		}

		long nowEpoch = Instant.now().getEpochSecond();

		for (GroupCompetition competition : competitions)
		{
			if (competition.startDateUnix <= nowEpoch && nowEpoch <= competition.endDateUnix)
			{
				sendMessage("Competition currently running: " + competition.name);
			}
		}
	}

	private void fireReminder(GroupCompetition competition, int thresholdMinutes)
	{
		String message = thresholdMinutes <= 0
			? competition.name + " starts now!"
			: TimeUtil.describeThresholdMinutes(thresholdMinutes) + " until " + competition.name + " starts";
		sendMessage(message);
	}

	private void sendMessage(String text)
	{
		String formatted = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append(text)
			.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(formatted)
			.build());
	}

	private String reminderKey(int competitionId, int thresholdMinutes)
	{
		return competitionId + ":" + thresholdMinutes;
	}
}

package com.smokescapehub.reminders;

import com.smokescapehub.SmokeScapeHubConfig;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

// A joke feature for a cannabis-themed clan. Meant to be scheduled to run
// precisely at :20 past every hour (see SmokeScapeHubPlugin) - since every
// location below is a whole-hour UTC offset, checking exactly at UTC :20
// means every one of them is also showing :20 local (a whole-hour shift
// only changes the hour, never the minute), so whichever city has local
// hour 4 or 16 at that moment is *actually* at 4:20, not just "4-ish."
// LOCATIONS spans roughly every hour-wide offset band with no gaps, so
// there's always a real match at every scheduled check.
public class FourTwentyReminder
{
	// Tolerance for scheduler jitter (the task firing a few seconds into the
	// next minute) - not meant to widen the window beyond an honest ":20".
	private static final int MINUTE_TOLERANCE = 1;

	private static final Map<String, String> LOCATIONS = buildLocations();

	private final ChatMessageManager chatMessageManager;
	private final SmokeScapeHubConfig config;

	@Inject
	public FourTwentyReminder(ChatMessageManager chatMessageManager, SmokeScapeHubConfig config)
	{
		this.chatMessageManager = chatMessageManager;
		this.config = config;
	}

	// Call at :20 past the hour - see SmokeScapeHubPlugin's scheduling.
	public void tick()
	{
		if (!config.fourTwentyReminders())
		{
			return;
		}

		findFourTwentyLocation().ifPresent(this::announce);
	}

	private Optional<String> findFourTwentyLocation()
	{
		String best = null;
		int bestMinuteDistance = Integer.MAX_VALUE;

		for (Map.Entry<String, String> entry : LOCATIONS.entrySet())
		{
			ZonedDateTime local = ZonedDateTime.now(ZoneId.of(entry.getKey()));
			boolean rightHour = local.getHour() == 4 || local.getHour() == 16;
			int minuteDistance = Math.abs(local.getMinute() - 20);

			if (!rightHour || minuteDistance > MINUTE_TOLERANCE)
			{
				continue;
			}

			if (minuteDistance < bestMinuteDistance)
			{
				bestMinuteDistance = minuteDistance;
				best = entry.getValue();
			}
		}

		return Optional.ofNullable(best);
	}

	private void announce(String location)
	{
		String formatted = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("It's 4:20 in " + location + "!")
			.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(formatted)
			.build());
	}

	// Every entry is a whole-hour UTC offset - no half/quarter-hour zones
	// (e.g. India) are included, since those would show :50 or :05 instead
	// of :20 when checked at UTC's :20 mark, breaking the "actually 4:20"
	// guarantee this whole feature depends on.
	private static Map<String, String> buildLocations()
	{
		Map<String, String> map = new LinkedHashMap<>();
		map.put("Pacific/Midway", "Midway Island");
		map.put("Pacific/Honolulu", "Honolulu");
		map.put("America/Anchorage", "Anchorage");
		map.put("America/Los_Angeles", "Los Angeles");
		map.put("America/Denver", "Denver");
		map.put("America/Chicago", "Chicago");
		map.put("America/New_York", "New York");
		map.put("America/Halifax", "Halifax");
		map.put("America/Sao_Paulo", "Sao Paulo");
		map.put("America/Noronha", "Fernando de Noronha");
		map.put("Atlantic/Azores", "the Azores");
		map.put("Europe/London", "London");
		map.put("Europe/Paris", "Paris");
		map.put("Europe/Athens", "Athens");
		map.put("Europe/Moscow", "Moscow");
		map.put("Asia/Dubai", "Dubai");
		map.put("Asia/Karachi", "Karachi");
		map.put("Asia/Dhaka", "Dhaka");
		map.put("Asia/Bangkok", "Bangkok");
		map.put("Asia/Shanghai", "Shanghai");
		map.put("Asia/Tokyo", "Tokyo");
		map.put("Australia/Sydney", "Sydney");
		map.put("Pacific/Guadalcanal", "Honiara");
		map.put("Pacific/Auckland", "Auckland");
		map.put("Pacific/Fiji", "Fiji");
		return map;
	}
}

package com.smokescapehub;

import com.google.inject.Provides;
import com.smokescapehub.reminders.CompetitionReminderManager;
import com.smokescapehub.reminders.FourTwentyReminder;
import java.time.Duration;
import java.time.ZonedDateTime;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Smoke Scape Hub",
	description = "Clan milestones, competitions, leaderboards and Discord link, powered by TempleOSRS",
	tags = {"clan", "templeosrs", "milestones", "competitions", "discord"}
)
public class SmokeScapeHubPlugin extends Plugin
{
	private static final String TEMPLE_GROUP_ID = "27";
	private static final int REFRESH_HOURS = 1;
	private static final int REMINDER_TICK_MINUTES = 1;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private SmokeScapeHubPanel panel;

	@Inject
	private CompetitionReminderManager reminderManager;

	@Inject
	private FourTwentyReminder fourTwentyReminder;

	@Inject
	private ScheduledExecutorService executor;

	private NavigationButton navButton;
	private ScheduledFuture<?> refreshTask;
	private ScheduledFuture<?> reminderTask;
	private ScheduledFuture<?> fourTwentyTask;

	@Override
	protected void startUp()
	{
		navButton = NavigationButton.builder()
			.tooltip("Smoke Scape Hub")
			.icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
			.priority(5)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);

		reminderManager.init();
		refreshAll();

		refreshTask = executor.scheduleWithFixedDelay(this::refreshAll, REFRESH_HOURS, REFRESH_HOURS, TimeUnit.HOURS);
		reminderTask = executor.scheduleWithFixedDelay(reminderManager::tick, REMINDER_TICK_MINUTES, REMINDER_TICK_MINUTES, TimeUnit.MINUTES);

		// Must land on :20 past the hour for "4:20" to actually mean 4:20,
		// not just "some time in the 4 o'clock hour" - see FourTwentyReminder.
		long initialDelayMs = millisUntilNextTwentyPastHour();
		fourTwentyTask = executor.scheduleAtFixedRate(fourTwentyReminder::tick,
			initialDelayMs, TimeUnit.HOURS.toMillis(1), TimeUnit.MILLISECONDS);
	}

	@Override
	protected void shutDown()
	{
		if (refreshTask != null)
		{
			refreshTask.cancel(true);
			refreshTask = null;
		}

		if (reminderTask != null)
		{
			reminderTask.cancel(true);
			reminderTask = null;
		}

		if (fourTwentyTask != null)
		{
			fourTwentyTask.cancel(true);
			fourTwentyTask = null;
		}

		clientToolbar.removeNavigation(navButton);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		reminderManager.onGameStateChanged(event.getGameState());
	}

	private void refreshAll()
	{
		panel.refreshAll();
		reminderManager.refresh(TEMPLE_GROUP_ID);
	}

	private static long millisUntilNextTwentyPastHour()
	{
		ZonedDateTime now = ZonedDateTime.now();
		ZonedDateTime target = now.withMinute(20).withSecond(0).withNano(0);
		if (!target.isAfter(now))
		{
			target = target.plusHours(1);
		}
		return Duration.between(now, target).toMillis();
	}

	@Provides
	SmokeScapeHubConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SmokeScapeHubConfig.class);
	}
}

