package com.smokescapehub.util;

import java.time.Duration;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;

public final class TimeUtil
{
	private static final DateTimeFormatter TEMPLE_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

	private TimeUtil()
	{
	}

	// TempleOSRS timestamps are "yyyy-MM-dd HH:mm:ss" server time, which TempleOSRS documents as UTC.
	public static Instant parseTempleDate(String date)
	{
		try
		{
			return LocalDateTime.parse(date, TEMPLE_DATE_FORMAT).atZone(ZoneOffset.UTC).toInstant();
		}
		catch (Exception e)
		{
			return Instant.EPOCH;
		}
	}

	public static String ago(Instant time)
	{
		return describe(Duration.between(time, Instant.now())) + " ago";
	}

	public static String until(Instant time)
	{
		Duration duration = Duration.between(Instant.now(), time);
		if (duration.isNegative())
		{
			return "any moment";
		}
		return "in " + describe(duration);
	}

	private static String describe(Duration duration)
	{
		long minutes = Math.abs(duration.toMinutes());
		if (minutes < 1)
		{
			return "moments";
		}
		if (minutes < 60)
		{
			return minutes + "m";
		}
		long hours = Math.abs(duration.toHours());
		if (hours < 24)
		{
			return hours + "h";
		}
		long days = Math.abs(duration.toDays());
		return days + "d";
	}

	// Formats a reminder threshold (e.g. 1440 -> "24 hours", 30 -> "30 minutes").
	public static String describeThresholdMinutes(int minutes)
	{
		if (minutes <= 0)
		{
			return "now";
		}
		if (minutes < 60)
		{
			return minutes + (minutes == 1 ? " minute" : " minutes");
		}
		int hours = minutes / 60;
		return hours + (hours == 1 ? " hour" : " hours");
	}
}

package com.smokescapehub.util;

import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import net.runelite.client.plugins.hiscore.HiscorePlugin;
import net.runelite.client.util.ImageUtil;

// Ironman/HCIM/UIM icons borrowed from RuneLite's own built-in Hiscore panel
// resources, rather than bundling separate copies - same icons players
// already recognize. Keyed by TempleOSRS's game_mode field (0 = Main,
// 1 = Ironman, 2 = Ultimate Ironman, 3 = Hardcore Ironman).
public final class GameModeIcons
{
	private static final int ICON_SIZE = 14;
	private static final Map<Integer, Icon> ICONS = build();

	private GameModeIcons()
	{
	}

	public static Icon get(int gameMode)
	{
		return ICONS.get(gameMode);
	}

	private static Map<Integer, Icon> build()
	{
		Map<Integer, Icon> icons = new HashMap<>();
		putIfLoaded(icons, 1, "ironman.png");
		putIfLoaded(icons, 2, "ultimate_ironman.png");
		putIfLoaded(icons, 3, "hardcore_ironman.png");
		return icons;
	}

	private static void putIfLoaded(Map<Integer, Icon> icons, int gameMode, String resourceName)
	{
		try
		{
			BufferedImage image = ImageUtil.loadImageResource(HiscorePlugin.class, resourceName);
			icons.put(gameMode, new ImageIcon(ImageUtil.resizeImage(image, ICON_SIZE, ICON_SIZE)));
		}
		catch (Exception e)
		{
			// If RuneLite ever renames/removes these, rows just show no icon.
		}
	}
}

