public class CompetitionsPanel extends JPanel
{
	private static final long MAX_UPCOMING_SECONDS = 14L * 24 * 60 * 60;
	private static final int COLLAPSED_TOP_N = 5;
	private static final int EXPANDED_TOP_N = 25;
	private static final int ROW_HEIGHT = 22;
	// Same alternating pair TempleOSRS's own plugin uses for its ranking rows.
	private static final Color[] ROW_COLORS = {ColorScheme.DARK_GRAY_HOVER_COLOR, ColorScheme.DARKER_GRAY_COLOR};

	private final TempleOsrsClient client;
	private final JPanel listPanel = new JPanel();
	private final JLabel statusLabel = new JLabel();

	public CompetitionsPanel(TempleOsrsClient client)
	{
		this.client = client;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
		listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		statusLabel.setForeground(Color.GRAY);
		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		add(statusLabel, BorderLayout.NORTH);
		add(listPanel, BorderLayout.CENTER);
	}

	public void refresh(String groupId)
	{
		if (groupId == null || groupId.trim().isEmpty())
		{
			showStatus("Set a TempleOSRS Group ID in the plugin settings.");
			return;
		}

		showStatus("Loading competitions...");

		client.getGroupCompetitions(groupId.trim(),
			competitions -> SwingUtilities.invokeLater(() -> populate(competitions)),
			error -> SwingUtilities.invokeLater(() -> showStatus("Failed to load competitions. Check the Group ID.")));
	}

	private void populate(List<GroupCompetition> competitions)
	{
		listPanel.removeAll();

		long nowEpoch = Instant.now().getEpochSecond();

		List<GroupCompetition> relevant = (competitions == null ? Collections.<GroupCompetition>emptyList() : competitions).stream()
			.filter(c -> c.status == 1 || (c.status == 0 && c.startDateUnix - nowEpoch <= MAX_UPCOMING_SECONDS))
			.sorted(Comparator.comparingInt((GroupCompetition c) -> c.status == 1 ? 0 : 1)
				.thenComparingLong(c -> c.startDateUnix))
			.collect(Collectors.toList());

		if (relevant.isEmpty())
		{
			showStatus("No active or upcoming competitions.");
			revalidate();
			repaint();
			return;
		}

		statusLabel.setText("");

		for (GroupCompetition competition : relevant)
		{
			listPanel.add(buildCard(competition));
		}

		revalidate();
		repaint();
	}

	private JPanel buildCard(GroupCompetition competition)
	{
		boolean ongoing = competition.status == 1;

		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		JLabel titleLabel = new JLabel(competition.name == null ? "Competition" : competition.name);
		titleLabel.setForeground(Color.WHITE);
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setAlignmentX(0f);

		String timing = ongoing
			? "Ends " + TimeUtil.until(Instant.ofEpochSecond(competition.endDateUnix))
			: "Starts " + TimeUtil.until(Instant.ofEpochSecond(competition.startDateUnix));

		JLabel metaLabel = new JLabel(prettySkill(competition.skill) + "  •  " + timing);
		metaLabel.setForeground(Color.LIGHT_GRAY);
		metaLabel.setFont(FontManager.getRunescapeSmallFont());
		metaLabel.setAlignmentX(0f);

		JPanel standings = new JPanel();
		standings.setLayout(new BoxLayout(standings, BoxLayout.Y_AXIS));
		standings.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		standings.setAlignmentX(0f);
		standings.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));

		card.add(titleLabel);
		card.add(metaLabel);
		card.add(standings);

		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		wrapper.add(card, BorderLayout.CENTER);
		wrapper.setAlignmentX(0f);

		if (ongoing)
		{
			JLabel loading = new JLabel("Loading standings...");
			loading.setForeground(Color.GRAY);
			loading.setFont(FontManager.getRunescapeSmallFont());
			standings.add(loading);

			client.getCompetitionParticipants(competition.id,
				participants -> SwingUtilities.invokeLater(() -> populateStandings(standings, participants)),
				error -> SwingUtilities.invokeLater(() -> populateStandingsError(standings)));
		}

		return wrapper;
	}

	private void populateStandings(JPanel standings, List<CompetitionParticipant> participants)
	{
		List<CompetitionParticipant> sorted = participants == null ? Collections.emptyList() : participants.stream()
			.sorted(Comparator.comparingLong((CompetitionParticipant p) -> p.xpGained).reversed())
			.limit(EXPANDED_TOP_N)
			.collect(Collectors.toList());

		renderStandings(standings, sorted, false);
	}

	private void renderStandings(JPanel standings, List<CompetitionParticipant> sorted, boolean expanded)
	{
		standings.removeAll();

		if (sorted.isEmpty())
		{
			JLabel none = new JLabel("No participants yet.");
			none.setForeground(Color.GRAY);
			none.setFont(FontManager.getRunescapeSmallFont());
			standings.add(none);
		}
		else
		{
			int shown = Math.min(expanded ? EXPANDED_TOP_N : COLLAPSED_TOP_N, sorted.size());

			int rank = 1;
			for (CompetitionParticipant p : sorted.subList(0, shown))
			{
				String name = p.username == null ? "Unknown" : p.username;
				standings.add(buildParticipantRow(rank, name, p.xpGained));
				rank++;
			}

			if (sorted.size() > COLLAPSED_TOP_N)
			{
				JButton toggle = new JButton(expanded ? "Show less" : "Show more");
				toggle.setFocusPainted(false);
				toggle.setFont(FontManager.getRunescapeSmallFont());
				toggle.setAlignmentX(0f);
				toggle.setBorder(BorderFactory.createCompoundBorder(
					BorderFactory.createEmptyBorder(4, 0, 0, 0),
					BorderFactory.createCompoundBorder(
						BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
						BorderFactory.createEmptyBorder(3, 8, 3, 8))));
				toggle.addActionListener(e -> renderStandings(standings, sorted, !expanded));
				standings.add(toggle);
			}
		}

		standings.revalidate();
		listPanel.revalidate();
		listPanel.repaint();
	}

	private JPanel buildParticipantRow(int rank, String name, long xpGained)
	{
		JPanel row = new JPanel(new GridLayout(1, 2));
		row.setBackground(ROW_COLORS[rank % 2]);
		row.setAlignmentX(0f);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));
		row.setPreferredSize(new Dimension(0, ROW_HEIGHT));

		JLabel nameLabel = new JLabel(rank + ". " + name);
		nameLabel.setBorder(BorderFactory.createEmptyBorder(0, 5, 0, 0));
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setFont(FontManager.getRunescapeSmallFont());
		row.add(nameLabel);

		JLabel valueLabel = new JLabel(QuantityFormatter.quantityToStackSize(xpGained));
		valueLabel.setBorder(BorderFactory.createEmptyBorder(0, 5, 0, 0));
		valueLabel.setForeground(ColorScheme.GRAND_EXCHANGE_PRICE);
		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		row.add(valueLabel);

		return row;
	}

	private void populateStandingsError(JPanel standings)
	{
		standings.removeAll();
		JLabel err = new JLabel("Couldn't load standings.");
		err.setForeground(Color.GRAY);
		err.setFont(FontManager.getRunescapeSmallFont());
		standings.add(err);
		standings.revalidate();
		listPanel.revalidate();
		listPanel.repaint();
	}

	private String prettySkill(String skill)
	{
		if (skill == null || skill.isEmpty())
		{
			return "Overall";
		}
		String[] words = skill.replace('_', ' ').split(" ");
		StringBuilder sb = new StringBuilder();
		for (String w : words)
		{
			if (w.isEmpty())
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(' ');
			}
			sb.append(Character.toUpperCase(w.charAt(0))).append(w.substring(1).toLowerCase(Locale.ROOT));
		}
		return sb.toString();
	}

	private void showStatus(String text)
	{
		listPanel.removeAll();
		statusLabel.setText(text);
		revalidate();
		repaint();
	}
}

package com.smokescapehub.panels;

import com.smokescapehub.temple.CollectionLogMember;
import com.smokescapehub.temple.GroupMemberStats;
import com.smokescapehub.temple.PetItems;
import com.smokescapehub.temple.TempleOsrsClient;
import com.smokescapehub.util.GameModeIcons;
import com.smokescapehub.util.SlickScrollBarUI;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;
import net.runelite.client.util.QuantityFormatter;

public class LeaderboardsPanel extends JPanel
{
	private static final int TOP_N = 20;
	private static final int ROW_HEIGHT = 22;
	// Same alternating pair TempleOSRS's own plugin uses for its ranking rows.
	private static final Color[] ROW_COLORS = {ColorScheme.DARK_GRAY_HOVER_COLOR, ColorScheme.DARKER_GRAY_COLOR};

	private final TempleOsrsClient client;
	private final RankedListView petView = new RankedListView();
	private final RankedListView clogView = new RankedListView();
	private final RankedListView ehpView = new RankedListView();
	private final RankedListView ehbView = new RankedListView();

	public LeaderboardsPanel(TempleOsrsClient client)
	{
		this.client = client;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel display = new JPanel();
		display.setBackground(ColorScheme.DARK_GRAY_COLOR);

		MaterialTabGroup subTabs = new MaterialTabGroup(display);
		subTabs.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		subTabs.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		subTabs.setLayout(new GridLayout(1, 4, 2, 0));

		MaterialTab ehpTab = new MaterialTab("EHP", subTabs, scroll(ehpView.root));
		MaterialTab ehbTab = new MaterialTab("EHB", subTabs, scroll(ehbView.root));
		MaterialTab clogTab = new MaterialTab("Clog", subTabs, scroll(clogView.root));
		MaterialTab petTab = new MaterialTab("Pets", subTabs, scroll(petView.root));

		subTabs.addTab(ehpTab);
		subTabs.addTab(ehbTab);
		subTabs.addTab(clogTab);
		subTabs.addTab(petTab);

		add(subTabs, BorderLayout.NORTH);
		add(display, BorderLayout.CENTER);

		subTabs.select(ehpTab);
	}

	public void refresh(String groupId)
	{
		if (groupId == null || groupId.trim().isEmpty())
		{
			String message = "Set a TempleOSRS Group ID in the plugin settings.";
			petView.showStatus(message);
			clogView.showStatus(message);
			ehpView.showStatus(message);
			ehbView.showStatus(message);
			return;
		}

		String id = groupId.trim();

		// Pets are derived from the same collection log fetch (see PetItems) -
		// TempleOSRS's dedicated pet-tracking endpoint has almost no data.
		petView.showStatus("Loading...");
		clogView.showStatus("Loading...");
		client.getCollectionLogLeaderboard(id,
			members -> SwingUtilities.invokeLater(() ->
			{
				populateClog(members);
				populatePets(members);
			}),
			error -> SwingUtilities.invokeLater(() ->
			{
				clogView.showStatus("Failed to load the collection log leaderboard.");
				petView.showStatus("Failed to load pet counts.");
			}));

		ehpView.showStatus("Loading...");
		ehbView.showStatus("Loading...");
		client.getMemberStats(id,
			members -> SwingUtilities.invokeLater(() -> populateEhpEhb(members)),
			error -> SwingUtilities.invokeLater(() ->
			{
				ehpView.showStatus("Failed to load EHP standings.");
				ehbView.showStatus("Failed to load EHB standings.");
			}));
	}

	private void populatePets(List<CollectionLogMember> members)
	{
		List<CollectionLogMember> sorted = (members == null ? Collections.<CollectionLogMember>emptyList() : members).stream()
			.filter(m -> PetItems.countPets(m.items) > 0)
			.sorted(Comparator.comparingInt((CollectionLogMember m) -> PetItems.countPets(m.items)).reversed())
			.limit(TOP_N)
			.collect(Collectors.toList());

		petView.showRows(sorted.stream()
			.map(m -> {
				int count = PetItems.countPets(m.items);
				String value = QuantityFormatter.quantityToStackSize(count) + (count == 1 ? " pet" : " pets");
				return new Row(clogName(m), value, GameModeIcons.get(m.gameMode));
			})
			.collect(Collectors.toList()));
	}

	private void populateClog(List<CollectionLogMember> members)
	{
		List<CollectionLogMember> sorted = (members == null ? Collections.<CollectionLogMember>emptyList() : members).stream()
			.sorted(Comparator.comparingInt((CollectionLogMember m) -> m.totalCollectionsFinished).reversed())
			.limit(TOP_N)
			.collect(Collectors.toList());

		clogView.showRows(sorted.stream()
			.map(m -> new Row(clogName(m), QuantityFormatter.quantityToStackSize(m.totalCollectionsFinished) + " items", GameModeIcons.get(m.gameMode)))
			.collect(Collectors.toList()));
	}

	private void populateEhpEhb(List<GroupMemberStats> members)
	{
		List<GroupMemberStats> nonNull = members == null ? Collections.emptyList() : members;

		List<GroupMemberStats> byEhp = nonNull.stream()
			.filter(m -> m.skills != null && m.skills.ehp > 0)
			.sorted(Comparator.comparingDouble((GroupMemberStats m) -> m.skills.ehp).reversed())
			.limit(TOP_N)
			.collect(Collectors.toList());

		ehpView.showRows(byEhp.stream()
			.map(m -> new Row(memberName(m), QuantityFormatter.quantityToStackSize(Math.round(m.skills.ehp)) + " EHP", GameModeIcons.get(m.gameMode)))
			.collect(Collectors.toList()));

		List<GroupMemberStats> byEhb = nonNull.stream()
			.filter(m -> m.bosses != null && m.bosses.ehb > 0)
			.sorted(Comparator.comparingDouble((GroupMemberStats m) -> m.bosses.ehb).reversed())
			.limit(TOP_N)
			.collect(Collectors.toList());

		ehbView.showRows(byEhb.stream()
			.map(m -> new Row(memberName(m), QuantityFormatter.quantityToStackSize(Math.round(m.bosses.ehb)) + " EHB", GameModeIcons.get(m.gameMode)))
			.collect(Collectors.toList()));
	}

	private String clogName(CollectionLogMember m)
	{
		return m.playerNameWithCapitalization != null && !m.playerNameWithCapitalization.isEmpty()
			? m.playerNameWithCapitalization
			: (m.player == null ? "Unknown" : m.player);
	}

	private String memberName(GroupMemberStats m)
	{
		return m.playerNameWithCapitalization != null && !m.playerNameWithCapitalization.isEmpty()
			? m.playerNameWithCapitalization
			: (m.player == null ? "Unknown" : m.player);
	}

	private JScrollPane scroll(JPanel content)
	{
		JScrollPane scrollPane = new JScrollPane(content);
		scrollPane.setBorder(BorderFactory.createEmptyBorder());
		scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scrollPane.getVerticalScrollBar().setUI(new SlickScrollBarUI());
		scrollPane.getVerticalScrollBar().setUnitIncrement(16);
		return scrollPane;
	}

	private static final class Row
	{
		final String name;
		final String value;
		final Icon icon;

		Row(String name, String value, Icon icon)
		{
			this.name = name;
			this.value = value;
			this.icon = icon;
		}
	}

	private static final class RankedListView
	{
		final JPanel root = new JPanel(new BorderLayout());
		final JPanel listPanel = new JPanel();
		final JLabel statusLabel = new JLabel();

		RankedListView()
		{
			root.setBackground(ColorScheme.DARK_GRAY_COLOR);

			listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
			listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

			statusLabel.setForeground(Color.GRAY);
			statusLabel.setFont(FontManager.getRunescapeSmallFont());
			statusLabel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

			root.add(statusLabel, BorderLayout.NORTH);
			root.add(listPanel, BorderLayout.CENTER);
		}

		void showStatus(String text)
		{
			listPanel.removeAll();
			statusLabel.setText(text);
			listPanel.revalidate();
			listPanel.repaint();
		}

		void showRows(List<Row> rows)
		{
			listPanel.removeAll();

			if (rows.isEmpty())
			{
				statusLabel.setText("No data yet.");
				listPanel.revalidate();
				listPanel.repaint();
				return;
			}

			statusLabel.setText("");
			for (int i = 0; i < rows.size(); i++)
			{
				listPanel.add(buildRow(i + 1, rows.get(i)));
			}

			listPanel.revalidate();
			listPanel.repaint();
		}

		private JPanel buildRow(int rank, Row row)
		{
			JPanel panel = new JPanel(new GridLayout(1, 2));
			panel.setBackground(ROW_COLORS[rank % 2]);
			panel.setPreferredSize(new Dimension(0, ROW_HEIGHT));
			panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));

			// Rank and name are separate labels, not one "8. Name" string, so
			// the mode icon (set via JLabel#setIcon, which always renders to
			// the left of that label's own text) lands between the rank and
			// the name - "8. [icon]Name" - instead of in front of the rank.
			JPanel left = new JPanel();
			left.setLayout(new BoxLayout(left, BoxLayout.X_AXIS));
			left.setBackground(ROW_COLORS[rank % 2]);
			left.setBorder(BorderFactory.createEmptyBorder(0, 5, 0, 0));

			JLabel rankLabel = new JLabel(rank + ".");
			rankLabel.setForeground(Color.WHITE);
			rankLabel.setFont(FontManager.getRunescapeSmallFont());

			JLabel nameLabel = new JLabel(row.name);
			nameLabel.setBorder(BorderFactory.createEmptyBorder(0, 4, 0, 0));
			nameLabel.setForeground(Color.WHITE);
			nameLabel.setFont(FontManager.getRunescapeSmallFont());
			if (row.icon != null)
			{
				nameLabel.setIcon(row.icon);
				nameLabel.setIconTextGap(4);
			}

			left.add(rankLabel);
			left.add(nameLabel);

			JLabel valueLabel = new JLabel(row.value);
			valueLabel.setBorder(BorderFactory.createEmptyBorder(0, 5, 0, 0));
			valueLabel.setForeground(ColorScheme.GRAND_EXCHANGE_PRICE);
			valueLabel.setFont(FontManager.getRunescapeSmallFont());

			panel.add(left);
			panel.add(valueLabel);

			return panel;
		}
	}
}

package com.smokescapehub.panels;

import com.smokescapehub.temple.GroupAchievement;
import com.smokescapehub.temple.GroupMemberStats;
import com.smokescapehub.temple.RecentCollectionItem;
import com.smokescapehub.temple.TempleOsrsClient;
import com.smokescapehub.util.GameModeIcons;
import com.smokescapehub.util.TimeUtil;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.QuantityFormatter;

// Merges two TempleOSRS feeds into one "Recent" list, newest first:
// group achievements (99s, boss KC milestones) and notable recent
// collection log unlocks (pets, rare clue items, etc). The two calls
// finish independently, so each just updates its own field and
// re-renders the combined, sorted result.
public class MilestonesPanel extends JPanel
{
	private static final int MAX_ENTRIES = 30;
	// Same alternating pair TempleOSRS's own plugin uses for its ranking rows.
	private static final Color[] ROW_COLORS = {ColorScheme.DARK_GRAY_HOVER_COLOR, ColorScheme.DARKER_GRAY_COLOR};

	private final TempleOsrsClient client;
	private final JPanel listPanel = new JPanel();
	private final JLabel statusLabel = new JLabel();

	private List<GroupAchievement> latestAchievements = Collections.emptyList();
	private List<RecentCollectionItem> latestRecentItems = Collections.emptyList();
	private Map<String, Integer> gameModeByPlayer = Collections.emptyMap();
	private boolean achievementsLoaded;
	private boolean recentItemsLoaded;

	public MilestonesPanel(TempleOsrsClient client)
	{
		this.client = client;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
		listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		statusLabel.setForeground(Color.GRAY);
		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		add(statusLabel, BorderLayout.NORTH);
		add(listPanel, BorderLayout.CENTER);
	}

	public void refresh(String groupId)
	{
		if (groupId == null || groupId.trim().isEmpty())
		{
			showStatus("Set a TempleOSRS Group ID in the plugin settings.");
			return;
		}

		achievementsLoaded = false;
		recentItemsLoaded = false;
		showStatus("Loading...");

		String id = groupId.trim();

		client.getGroupAchievements(id,
			achievements -> SwingUtilities.invokeLater(() ->
			{
				latestAchievements = achievements != null ? achievements : Collections.emptyList();
				achievementsLoaded = true;
				render();
			}),
			error -> SwingUtilities.invokeLater(() ->
			{
				achievementsLoaded = true;
				render();
			}));

		client.getGroupRecentItems(id,
			items -> SwingUtilities.invokeLater(() ->
			{
				latestRecentItems = items != null ? items : Collections.emptyList();
				recentItemsLoaded = true;
				render();
			}),
			error -> SwingUtilities.invokeLater(() ->
			{
				recentItemsLoaded = true;
				render();
			}));

		// Achievements and recent items don't carry a game_mode field of
		// their own - it's derived from the same member stats lookup the
		// Leaderboards tab uses, keyed by player name, purely for the
		// ironman/HCIM/UIM icon.
		client.getMemberStats(id,
			members -> SwingUtilities.invokeLater(() ->
			{
				Map<String, Integer> map = new HashMap<>();
				if (members != null)
				{
					for (GroupMemberStats m : members)
					{
						if (m.player != null)
						{
							map.put(m.player.toLowerCase(Locale.ROOT), m.gameMode);
						}
					}
				}
				gameModeByPlayer = map;
				render();
			}),
			error -> { });
	}

	private void render()
	{
		List<Entry> entries = new ArrayList<>();

		for (GroupAchievement a : latestAchievements)
		{
			String name = a.username == null ? "Unknown" : a.username;
			entries.add(new Entry(TimeUtil.parseTempleDate(a.date), name, describeMilestone(a), iconFor(name)));
		}

		for (RecentCollectionItem item : latestRecentItems)
		{
			String name = item.playerNameWithCapitalization != null && !item.playerNameWithCapitalization.isEmpty()
				? item.playerNameWithCapitalization
				: (item.player == null ? "Unknown" : item.player);
			entries.add(new Entry(Instant.ofEpochSecond(item.dateUnix), name, "Collection log: " + item.name, iconFor(name)));
		}

		if (entries.isEmpty())
		{
			if (achievementsLoaded && recentItemsLoaded)
			{
				showStatus("No recent activity found.");
			}
			return;
		}

		listPanel.removeAll();
		statusLabel.setText("");

		entries.sort(Comparator.comparing((Entry e) -> e.time).reversed());

		int index = 0;
		for (Entry entry : entries)
		{
			if (index >= MAX_ENTRIES)
			{
				break;
			}
			listPanel.add(createRow(entry, index));
			index++;
		}

		revalidate();
		repaint();
	}

	private JPanel createRow(Entry entry, int index)
	{
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setBackground(ROW_COLORS[index % 2]);
		row.setBorder(BorderFactory.createEmptyBorder(5, 8, 5, 8));
		row.setAlignmentX(0f);

		// Small, unbolded font to match the clean list style used on the
		// Comps and Leaderboards tabs, rather than the heavier bold look.
		JLabel nameLabel = new JLabel(entry.username);
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setFont(FontManager.getRunescapeSmallFont());
		nameLabel.setAlignmentX(0f);
		if (entry.icon != null)
		{
			nameLabel.setIcon(entry.icon);
			nameLabel.setIconTextGap(4);
		}

		String detail = entry.description + "  •  " + TimeUtil.ago(entry.time);
		JLabel detailLabel = new JLabel(detail);
		detailLabel.setForeground(Color.LIGHT_GRAY);
		detailLabel.setFont(FontManager.getRunescapeSmallFont());
		detailLabel.setAlignmentX(0f);

		row.add(nameLabel);
		row.add(detailLabel);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));

		return row;
	}

	private Icon iconFor(String username)
	{
		if (username == null)
		{
			return null;
		}
		Integer gameMode = gameModeByPlayer.get(username.toLowerCase(Locale.ROOT));
		return gameMode == null ? null : GameModeIcons.get(gameMode);
	}

	private String describeMilestone(GroupAchievement achievement)
	{
		String skill = achievement.skill == null ? "Unknown" : achievement.skill;

		if ("Pvm".equalsIgnoreCase(achievement.type))
		{
			return skill + " — " + QuantityFormatter.quantityToStackSize(achievement.xp) + " KC";
		}

		if ("Level".equalsIgnoreCase(achievement.milestone))
		{
			return skill + " level " + achievement.xp;
		}

		return skill + " — " + QuantityFormatter.quantityToStackSize(achievement.xp) + " XP";
	}

	private void showStatus(String text)
	{
		listPanel.removeAll();
		statusLabel.setText(text);
		revalidate();
		repaint();
	}

	private static final class Entry
	{
		final Instant time;
		final String username;
		final String description;
		final Icon icon;

		Entry(Instant time, String username, String description, Icon icon)
		{
			this.time = time;
			this.username = username;
			this.description = description;
			this.icon = icon;
		}
	}
}
